+    if (agora().getTime() >= Date.parse(encontros[0].inicio)) {
+      return res.status(422).json({
+        erro: 'ATIVIDADE_JA_INICIADA',
+        mensagem: 'Só é possível cancelar antes do início do 1º encontro.',
