+    }
+    banco.prepare('UPDATE atividades SET cancelada = 1 WHERE id = ?').run(atividade.id);
+    const linha = banco
+      .prepare('SELECT id, titulo, tipo, salaId, vagas, cancelada FROM atividades WHERE id = ?')
+      .get(atividade.id);
+    res.status(200).json(serializarAtividade(linha));
+  });
+
   return app;
 }
